--
-- Name: specboards_can_manage_product(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.specboards_can_manage_product(p_workspace uuid, p_product uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT specboards_is_member(p_workspace) AND (
    specboards_is_org_admin(p_workspace)
    OR EXISTS (
      SELECT 1 FROM product_members pm
      WHERE pm.product_id = p_product
        AND pm.user_id = nullif(current_setting('app.user_id', true), '')::uuid
        AND pm.role = 'admin'
    )
  );
$$;

--
-- Name: specboards_can_read_product(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.specboards_can_read_product(p_workspace uuid, p_product uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT specboards_is_member(p_workspace) AND (
    p_product IS NULL
    OR specboards_is_org_admin(p_workspace)
    OR EXISTS (SELECT 1 FROM products pr WHERE pr.id = p_product AND pr.visibility = 'org')
    OR EXISTS (
      SELECT 1 FROM product_members pm
      WHERE pm.product_id = p_product
        AND pm.user_id = nullif(current_setting('app.user_id', true), '')::uuid
    )
  );
$$;

--
-- Name: specboards_can_write_product(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.specboards_can_write_product(p_workspace uuid, p_product uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT specboards_is_member(p_workspace) AND (
    specboards_is_org_admin(p_workspace)
    OR EXISTS (
      SELECT 1 FROM product_members pm
      WHERE pm.product_id = p_product
        AND pm.user_id = nullif(current_setting('app.user_id', true), '')::uuid
        AND pm.role IN ('admin','contributor')
    )
  );
$$;

--
-- Name: specboards_is_member(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.specboards_is_member(target_workspace uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM members m
    WHERE m.workspace_id = target_workspace
      AND m.user_id = nullif(current_setting('app.user_id', true), '')::uuid
      AND m.deactivated_at IS NULL
  );
$$;

--
-- Name: specboards_is_org_admin(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.specboards_is_org_admin(target_workspace uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM members m
    WHERE m.workspace_id = target_workspace
      AND m.user_id = nullif(current_setting('app.user_id', true), '')::uuid
      AND m.role = 'owner'
      AND m.deactivated_at IS NULL
  );
$$;

--
-- Name: specboards_item_events_immutable(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.specboards_item_events_immutable() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  RAISE EXCEPTION 'item_events is append-only; record a new event instead of updating %', OLD.id;
END;
$$;

--
-- Name: specboards_resolve_provider_credential(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.specboards_resolve_provider_credential(p_workspace_id uuid, p_credential_id uuid) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT c.secret
  FROM model_provider_credentials c
  WHERE c.id = p_credential_id
    AND c.workspace_id = p_workspace_id
    -- The membership check is inside the function, not left to the caller.
    -- A SECURITY DEFINER function that trusted its arguments would be a way to
    -- read any workspace's credential by guessing two uuids.
    AND specboards_is_member(p_workspace_id);
$$;

