    created_at timestamp with time zone DEFAULT now() NOT NULL,
    proposal_outcome text,
    proposal_resolved_by uuid,
    proposal_resolved_at timestamp with time zone,
    proposal_commit_sha text,
    proposal_base_sha text,
    skill_key text,
    release_id uuid,
    CONSTRAINT assistant_messages_proposal_outcome_check CHECK (((proposal_outcome IS NULL) OR (proposal_outcome = ANY (ARRAY['accepted'::text, 'rejected'::text])))),
    CONSTRAINT assistant_messages_proposal_resolution_check CHECK ((((proposal_outcome IS NULL) AND (proposal_resolved_by IS NULL) AND (proposal_resolved_at IS NULL)) OR ((proposal_outcome IS NOT NULL) AND (proposal_resolved_by IS NOT NULL) AND (proposal_resolved_at IS NOT NULL)))),
    CONSTRAINT assistant_messages_role_check CHECK ((role = ANY (ARRAY['user'::text, 'assistant'::text]))),
    CONSTRAINT assistant_messages_subject_check CHECK ((num_nonnulls(feature_id, release_id) = 1))
);

