-- Name: activity_log; Type: ROW SECURITY; Schema: public; Owner: -
--

ALTER TABLE public.activity_log ENABLE ROW LEVEL SECURITY;

--
-- Name: activity_log activity_member_all; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY activity_member_all ON public.activity_log USING ((public.specboards_is_member(workspace_id) AND ((feature_id IS NULL) OR (EXISTS ( SELECT 1
   FROM public.features f
  WHERE ((f.id = activity_log.feature_id) AND public.specboards_can_read_product(f.workspace_id, f.product_id))))))) WITH CHECK (public.specboards_is_member(workspace_id));

