--
-- Name: assistant_messages assistant_messages_insert; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY assistant_messages_insert ON public.assistant_messages FOR INSERT WITH CHECK (public.specboards_is_member(workspace_id));

--
-- Name: assistant_messages assistant_messages_read; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY assistant_messages_read ON public.assistant_messages FOR SELECT USING (((EXISTS ( SELECT 1
   FROM public.features f
  WHERE ((f.id = assistant_messages.feature_id) AND public.specboards_can_read_product(f.workspace_id, f.product_id)))) OR (EXISTS ( SELECT 1
   FROM public.releases r
  WHERE ((r.id = assistant_messages.release_id) AND public.specboards_can_read_product(r.workspace_id, r.product_id))))));

--
-- Name: assistant_messages assistant_messages_update; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY assistant_messages_update ON public.assistant_messages FOR UPDATE USING (public.specboards_is_member(workspace_id)) WITH CHECK (public.specboards_is_member(workspace_id));

