--

CREATE POLICY detail_templates_read ON public.detail_templates FOR SELECT USING (
CASE
    WHEN (product_id IS NULL) THEN public.specboards_is_member(workspace_id)
    ELSE public.specboards_can_read_product(workspace_id, product_id)
END);

