-- Name: detail_templates detail_templates_write; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY detail_templates_write ON public.detail_templates USING (
CASE
    WHEN (product_id IS NULL) THEN public.specboards_is_org_admin(workspace_id)
    ELSE public.specboards_can_manage_product(workspace_id, product_id)
END) WITH CHECK (
CASE
    WHEN (product_id IS NULL) THEN public.specboards_is_org_admin(workspace_id)
    ELSE public.specboards_can_manage_product(workspace_id, product_id)
END);

